#!/data/data/com.termux/files/usr/bin/bash
set -Eeuo pipefail
cd "$HOME/companyos"
source "$HOME/.companyos_launch_env" 2>/dev/null || true

STAMP="$(date +%Y%m%d_%H%M%S)"
BK="$HOME/companyos/.companyos_backups/capability_request_executor_v11_$STAMP"
mkdir -p "$BK"
cp -a companyos/runtime/service_supervisor.py "$BK/" 2>/dev/null || true

echo "" | base64 -d > companyos/runtime/capability_request_executor.py
echo "" | base64 -d > scripts/companyos_requestctl
chmod +x scripts/companyos_requestctl
echo "" | base64 -d > tests/test_capability_request_executor_v11.py

echo "" | base64 -d > "$PREFIX/tmp/companyos_request_executor_patch.py"
python "$PREFIX/tmp/companyos_request_executor_patch.py"
rm -f "$PREFIX/tmp/companyos_request_executor_patch.py"

echo "[1/7] Compile"
python -m py_compile companyos/runtime/capability_request_executor.py companyos/runtime/service_supervisor.py tests/test_capability_request_executor_v11.py

echo "[2/7] Safety contract tests"
python -m unittest tests.test_capability_request_executor_v11 -v

echo "[3/7] Pending requests"
scripts/companyos_compoundctl requests || true

echo "[4/7] Execute one guarded request"
scripts/companyos_requestctl once | tee .companyos_runtime/capability_expansion/request_executor_v11_first_cycle.json || true

echo "[5/7] Refresh feedback"
scripts/companyos_feedbackctl once || true

echo "[6/7] Commit/push"
git add companyos/runtime/capability_request_executor.py companyos/runtime/service_supervisor.py scripts/companyos_requestctl tests/test_capability_request_executor_v11.py
git diff --cached --quiet || git commit -m "Close recursive capability request execution loop"
BRANCH="$(git branch --show-current)"
[ -n "$BRANCH" ] && git push origin "$BRANCH" || true

echo "[7/7] Restart + verify"
scripts/companyosctl restart || true
sleep 8

echo "===== REQUEST EXECUTOR ====="
scripts/companyos_requestctl status || true
echo "===== COMPOUNDING QUEUE ====="
scripts/companyos_compoundctl status || true
echo "===== EXPANSION INVENTORY ====="
scripts/companyos_expandctl inventory || true
echo "===== FEEDBACK ====="
scripts/companyos_feedbackctl status || true
echo "===== SERVICES ====="
scripts/companyosctl status || true

echo "BACKUP=$BK"
echo "COMPANYOS_RECURSIVE_CAPABILITY_LOOP_V11=PASS"
